// WT Filter — addProduct
$this->db->query("DELETE FROM `" . DB_PREFIX . "wt_filter_option_value_to_product` WHERE `product_id` = '" . (int)$product_id . "'");
if (isset($data['wt_filter_product_option']) && is_array($data['wt_filter_product_option'])) {
	foreach ($data['wt_filter_product_option'] as $option_id => $values) {
		if (empty($values['values']) || !is_array($values['values'])) {
			continue;
		}
		foreach ($values['values'] as $value_id => $value) {
			if (isset($value['selected'])) {
				$this->db->query("INSERT INTO `" . DB_PREFIX . "wt_filter_option_value_to_product` SET `product_id` = '" . (int)$product_id . "', `option_id` = '" . (int)$option_id . "', `value_id` = '" . $this->db->escape((string)$value_id) . "', `slide_value_min` = '" . (isset($value['slide_value_min']) ? (float)$value['slide_value_min'] : 0) . "', `slide_value_max` = '" . (isset($value['slide_value_max']) ? (float)$value['slide_value_max'] : 0) . "'");
			}
		}
	}
}

