operation.search:
public function getTotalSpecials(): int {
		$query = $this->db->query("SELECT COUNT(`ps`.`product_id`) AS `total` FROM (SELECT DISTINCT * FROM `" . DB_PREFIX . "product_discount` WHERE `customer_group_id` = '" . (int)$this->config->get('config_customer_group_id') . "' AND `quantity` = '1' AND `special` = '1' AND ((`date_end` = '0000-00-00' OR `date_end` > NOW()) AND (`date_start` = '0000-00-00' OR `date_start` < NOW())) GROUP BY `product_id`) `ps` LEFT JOIN `" . DB_PREFIX . "product_to_store` `p2s` ON (`ps`.`product_id` = `p2s`.`product_id`) LEFT JOIN `" . DB_PREFIX . "product` `p` ON (`p2s`.`product_id` = `p`.`product_id`) WHERE `p2s`.`store_id` = '" . (int)$this->config->get('config_store_id') . "' AND `p`.`status` = '1' AND `p`.`date_available` <= NOW()");

		if (isset($query->row['total'])) {
			return (int)$query->row['total'];
		} else {
			return 0;
		}
	}

operation.add:
public function getTotalSpecials(array $data = []): int {
		$sql = "SELECT COUNT(`ps`.`product_id`) AS `total` FROM (SELECT DISTINCT * FROM `" . DB_PREFIX . "product_discount` WHERE `customer_group_id` = '" . (int)$this->config->get('config_customer_group_id') . "' AND `quantity` = '1' AND `special` = '1' AND ((`date_end` = '0000-00-00' OR `date_end` > NOW()) AND (`date_start` = '0000-00-00' OR `date_start` < NOW())) GROUP BY `product_id`) `ps` LEFT JOIN `" . DB_PREFIX . "product_to_store` `p2s` ON (`ps`.`product_id` = `p2s`.`product_id`) LEFT JOIN `" . DB_PREFIX . "product` `p` ON (`p2s`.`product_id` = `p`.`product_id`) WHERE `p2s`.`store_id` = '" . (int)$this->config->get('config_store_id') . "' AND `p`.`status` = '1' AND `p`.`date_available` <= NOW()";

		// WT Filter
		if (!empty($data['filter_wt_filter'])) {
			$this->load->model('extension/wt_filter/catalog/wt_filter');
			$wt_filter_product_sql = $this->model_extension_wt_filter_catalog_wt_filter->getProductSQL($data['filter_wt_filter'], 0);
			if ($wt_filter_product_sql) {
				$sql .= $wt_filter_product_sql;
			}
		}

		$query = $this->db->query($sql);

		if (isset($query->row['total'])) {
			return (int)$query->row['total'];
		} else {
			return 0;
		}
	}

// WT Filter SEO
$data['filter_seo_text'] = '';
$data['filter_seo_crumb'] = false;
$seo_pos = $this->config->get('module_wt_filter_seo_text_position');
$data['filter_seo_position'] = ($seo_pos === 'above') ? 'above' : 'below';

if ($filter_wt_filter !== '') {
	$this->load->model('extension/wt_filter/catalog/wt_filter');
	$this->load->config('extension/wt_filter/wt_filter');
	$this->load->helper('extension/wt_filter/wt_filter');
	$wt_seo_params = $this->model_extension_wt_filter_catalog_wt_filter->decodeParams($filter_wt_filter);
	$wt_seo_page = $this->model_extension_wt_filter_catalog_wt_filter->getSeoPageByFilter($category_id, $wt_seo_params);
	if ($wt_seo_page) {
		$this->document->setTitle($wt_seo_page['meta_title']);
		$this->document->setDescription($wt_seo_page['meta_description']);
		$this->document->setKeywords($wt_seo_page['meta_keyword']);
		$data['heading_title'] = $wt_seo_page['h1'];
		$data['filter_seo_text'] = html_entity_decode($wt_seo_page['description'], ENT_QUOTES, 'UTF-8');
		$data['filter_seo_crumb'] = true;
		$data['breadcrumbs'][] = [
			'text' => $wt_seo_page['h1'],
			'href' => $this->request->server['REQUEST_URI'] ?? ''
		];
	}
}

